const MESES = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];

function escapeHtml(s) {
  return String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
function normalizeForma(forma) {
  return String(forma || '').normalize('NFD').replace(/\p{M}/gu,'').toLowerCase().replace(/\s+/g,' ').trim();
}
function paymentFamily(forma) {
  const f = normalizeForma(forma);
  if (/(binance|zelle)/.test(f)) return 'B';
  if (/(transferencia|pago\s*movil)/.test(f)) return 'C';
  return 'A';
}
function formatFechaEmision(dt, tz) {
  const d = dt.setZone(tz);
  return 'Tucacas, ' + d.toFormat('dd') + ' de ' + MESES[d.month - 1] + ' de ' + d.toFormat('yyyy');
}
function parseIsoDate(iso) {
  const m = String(iso || '').trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) throw new Error('Fecha inválida (YYYY-MM-DD): ' + iso);
  return { y: Number(m[1]), mo: Number(m[2]), d: Number(m[3]) };
}
function formatDisplayDate(iso) {
  const { y, mo, d } = parseIsoDate(iso);
  return String(d).padStart(2,'0') + '/' + String(mo).padStart(2,'0') + '/' + y;
}
function durationLabel(checkIn, checkOut) {
  const a = parseIsoDate(checkIn);
  const b = parseIsoDate(checkOut);
  const noches = Math.round((Date.UTC(b.y,b.mo-1,b.d) - Date.UTC(a.y,a.mo-1,a.d)) / 86400000);
  if (noches < 1) throw new Error('check_out debe ser posterior a check_in');
  return noches + ' NOCHES Y ' + (noches + 1) + ' DIAS';
}
function formatEur(n, spaced) {
  const num = Number(n);
  if (!Number.isFinite(num)) throw new Error('Monto EUR inválido: ' + n);
  const body = num.toLocaleString('es-VE', { minimumFractionDigits: Number.isInteger(num) ? 0 : 2, maximumFractionDigits: 2 });
  return spaced === false ? ('€' + body) : ('€ ' + body);
}
function formatBs(n) {
  const raw = String(n ?? '').trim();
  if (!raw) return '';
  if (/bs\.?\s*s/i.test(raw)) return raw.replace(/\s+/g,'');
  return 'Bs.S' + raw;
}
function cuentaCell(cuenta, nombreCliente) {
  const c = String(cuenta || '').trim();
  const extra = nombreCliente ? (' <small>' + escapeHtml(nombreCliente) + '</small>') : '';
  if (!c) return escapeHtml(nombreCliente || '');
  if (/@/.test(c) || /^https?:/i.test(c)) {
    const href = c.includes('@') && !c.startsWith('http') ? ('mailto:' + c) : c;
    return '<a href="' + escapeHtml(href) + '">' + escapeHtml(c) + '</a>' + extra;
  }
  return '<a href="#">' + escapeHtml(c) + '</a>' + extra;
}
function groupByFamily(pagos) {
  const groups = [];
  for (const row of pagos) {
    const fam = paymentFamily(row.forma);
    const last = groups[groups.length - 1];
    if (last && last.family === fam) last.rows.push(row);
    else groups.push({ family: fam, rows: [row] });
  }
  return groups;
}
function renderTableA(rows, nombreCliente) {
  const body = rows.map((r) => '<tr><td>' + escapeHtml(r.forma) + '</td><td class="right">' + escapeHtml(r.fecha) + '</td><td>' + cuentaCell(r.cuenta, nombreCliente) + '</td><td class="num">' + escapeHtml(formatBs(r.tasa_euro)) + '</td><td class="num">' + escapeHtml(formatEur(r.monto_eur)) + '</td></tr>').join('');
  return '<table class="pay"><colgroup><col style="width:104.1pt"><col style="width:55.9pt"><col style="width:142.7pt"><col style="width:107pt"><col style="width:88.9pt"></colgroup><thead><tr><td>Forma de pago</td><td>Fecha de pago</td><td>Cuenta</td><td class="arial">Tasa del Euro</td><td class="arial">Monto <span>€</span></td></tr></thead><tbody>' + body + '</tbody></table>';
}
function renderTableB(rows) {
  const body = rows.map((r) => '<tr><td>' + escapeHtml(r.forma) + '</td><td class="right">' + escapeHtml(r.fecha) + '</td><td>' + cuentaCell(r.cuenta) + '</td><td>' + escapeHtml(r.codigo_o_titular || '') + '</td><td class="num">' + escapeHtml(formatEur(r.monto_eur)) + '</td></tr>').join('');
  return '<table class="pay"><colgroup><col style="width:90pt"><col style="width:55pt"><col style="width:160pt"><col style="width:110pt"><col style="width:83pt"></colgroup><thead><tr><td>Forma de pago</td><td>Fecha de pago</td><td>Cuenta</td><td class="arial">Código / Titular</td><td class="arial">Monto <span>€</span></td></tr></thead><tbody>' + body + '</tbody></table>';
}
function renderTableC(rows) {
  const body = rows.map((r) => '<tr><td>' + escapeHtml(r.forma) + '</td><td class="right">' + escapeHtml(r.fecha) + '</td><td>' + cuentaCell(r.cuenta) + '</td><td>' + escapeHtml(r.ref_o_titular || r.codigo_o_titular || '') + '</td><td class="num">' + escapeHtml(formatBs(r.tasa_euro)) + '</td><td class="num">' + escapeHtml(formatBs(r.monto_bs)) + '</td><td class="num">' + escapeHtml(formatEur(r.monto_eur)) + '</td></tr>').join('');
  return '<table class="pay"><colgroup><col style="width:78pt"><col style="width:48pt"><col style="width:90pt"><col style="width:72pt"><col style="width:70pt"><col style="width:78pt"><col style="width:62pt"></colgroup><thead><tr><td>Forma de pago</td><td>Fecha</td><td>Cuenta</td><td class="arial">Ref. / Titular</td><td class="arial">Tasa €</td><td class="arial">Monto Bs.</td><td class="arial">Monto <span>€</span></td></tr></thead><tbody>' + body + '</tbody></table>';
}
function renderPagosHtml(pagos, nombreCliente) {
  if (!Array.isArray(pagos) || !pagos.length) throw new Error('pagos[] es obligatorio');
  return groupByFamily(pagos).map((g, i) => {
    const table = g.family === 'B' ? renderTableB(g.rows) : g.family === 'C' ? renderTableC(g.rows) : renderTableA(g.rows, i === 0 ? nombreCliente : '');
    return i === 0 ? table : ('<div class="gap12"></div>' + table);
  }).join('
');
}

const cfg = $('Config').first().json;
const trigger = (() => { try { return $('Cuando lo llama el 01').first().json || {}; } catch (e) { return {}; } })();
const hook = (() => { try { return $('Webhook prueba').first().json || {}; } catch (e) { return {}; } })();
const incoming = $input.first().json || {};
const body = (hook.body && typeof hook.body === 'object') ? hook.body : {};
const input = Object.assign({}, body, incoming, trigger);

const tz = String(cfg.timezone || 'America/Caracas');
const now = DateTime.now().setZone(tz);
const chatId = String(input.telegram_chat_id || '').trim();
if (!chatId) throw new Error('Falta telegram_chat_id');

const nombre = String(input.nombre || '').trim();
const cedula = String(input.cedula || '').trim();
const habitacion = String(input.habitacion || '').trim();
const checkIn = String(input.check_in || '').trim();
const checkOut = String(input.check_out || '').trim();
const pax = Number(input.pax);
const montoTotal = Number(input.monto_total_eur);
const estadoPago = String(input.estado_pago || 'PAGO COMPLETO').trim();
let pagos = input.pagos;
if (typeof pagos === 'string') {
  try { pagos = JSON.parse(pagos); } catch (e) { throw new Error('pagos debe ser JSON array'); }
}
if (!nombre || !cedula || !habitacion || !checkIn || !checkOut) {
  throw new Error('Faltan nombre, cedula, habitacion, check_in o check_out');
}
if (!Number.isFinite(pax) || pax < 1) throw new Error('pax inválido');
if (!Number.isFinite(montoTotal)) throw new Error('monto_total_eur inválido');

const duracion = durationLabel(checkIn, checkOut);
const fechaEmision = formatFechaEmision(now, tz);
const montoTotalLabel = formatEur(montoTotal, false);
const pagadoSum = pagos.reduce((s, r) => s + Number(r.monto_eur || 0), 0);
const montoPagadoLine = 'Monto Pagado: ' + formatEur(pagadoSum, false) + ' (' + estadoPago + ')';
const map = {
  '{{FECHA_EMISION}}': escapeHtml(fechaEmision),
  '{{NOMBRE}}': escapeHtml(nombre.toUpperCase()),
  '{{CEDULA}}': escapeHtml(cedula),
  '{{PLAN}}': escapeHtml(cfg.plan || DEFAULTS.plan),
  '{{PAX}}': escapeHtml(String(pax)),
  '{{DURACION}}': escapeHtml(duracion),
  '{{CHECK_IN}}': escapeHtml(formatDisplayDate(checkIn)),
  '{{CHECK_OUT}}': escapeHtml(formatDisplayDate(checkOut)),
  '{{HABITACION}}': escapeHtml(habitacion.toUpperCase()),
  '{{DESTINO}}': escapeHtml(cfg.destino || DEFAULTS.destino),
  '{{MONTO_TOTAL}}': escapeHtml(montoTotalLabel),
  '{{PAGOS_HTML}}': renderPagosHtml(pagos, nombre.toUpperCase()),
  '{{MONTO_PAGADO_LINE}}': escapeHtml(montoPagadoLine),
  '{{FIRMANTE_NOMBRE}}': escapeHtml(cfg.firmante_nombre || DEFAULTS.firmante_nombre),
  '{{FIRMANTE_CARGO}}': escapeHtml(cfg.firmante_cargo || DEFAULTS.firmante_cargo),
  '{{FIRMANTE_TEL}}': escapeHtml(cfg.firmante_tel || DEFAULTS.firmante_tel),
};
let html = TEMPLATE;
for (const [k, v] of Object.entries(map)) html = html.split(k).join(v);
if (/\{\{[A-Z0-9_]+\}\}/.test(html)) throw new Error('Placeholders sin reemplazar');

const filename = 'certificado-' + nombre.replace(/\s+/g, '-').toLowerCase() + '-' + checkIn + '.pdf';
const caption = 'Certificado de reserva — ' + nombre.toUpperCase() + ' (' + checkIn + ' → ' + checkOut + ')';
const binary = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'index.html', 'text/html');
return [{
  json: {
    telegram_chat_id: chatId,
    filename,
    caption,
    nombre: nombre.toUpperCase(),
    check_in: checkIn,
    check_out: checkOut,
    duracion,
    fecha_emision: fechaEmision,
  },
  binary: { data: binary },
}];

const meta = $('Armar HTML').first().json;
const item = $input.first();
const binKey = Object.keys(item.binary || {})[0];
if (!binKey) throw new Error('Gotenberg no devolvió PDF binario');
const pdf = item.binary[binKey];
pdf.fileName = meta.filename;
pdf.mimeType = 'application/pdf';
pdf.fileExtension = 'pdf';
return [{ json: meta, binary: { data: pdf } }];
